const month = $('Compute Previous Month (Digest)').first().json.month;
const monthLabel = $('Compute Previous Month (Digest)').first().json.monthLabel;
const isReal = (j) => j && Object.keys(j).length > 0;
const members = $('Read Members (Digest)').all().map(i => i.json).filter(j => isReal(j) && j.email);
const subs = $('Read Submissions (Digest)').all().map(i => i.json).filter(j => isReal(j) && j.member_email);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const splitLinks = (s) => String(s || '').split(/[\s,;]+/).filter(x => x.startsWith('http'));
const rows = members.map(m => {
  const email = String(m.email).trim().toLowerCase();
  const mine = subs
    .filter(s => String(s.member_email).trim().toLowerCase() === email && String(s.month).trim().slice(0, 7) === month)
    .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
  const s = mine[0];
  return {
    name: m.name,
    email: m.email,
    submitted: !!s,
    submission_date: s ? String(s.timestamp) : '',
    report_file: s ? String(s.report_file || '') : '',
    other_files: s ? splitLinks(s.other_files) : [],
  };
});
const submitted = rows.filter(r => r.submitted);
const missing = rows.filter(r => !r.submitted);
const total = rows.length;
const tr = rows.map(r => {
  const report = r.report_file ? '<a href="' + esc(r.report_file) + '">Report</a>' : '-';
  const others = r.other_files.length ? r.other_files.map((l, i) => '<a href="' + esc(l) + '">File ' + (i + 1) + '</a>').join(', ') : '-';
  const status = r.submitted ? '<span style="color:#1a7f37">Submitted</span>' : '<span style="color:#cf222e">Missing</span>';
  return '<tr><td style="padding:6px;border:1px solid #ddd">' + esc(r.name) + '</td><td style="padding:6px;border:1px solid #ddd">' + status + '</td><td style="padding:6px;border:1px solid #ddd">' + report + '</td><td style="padding:6px;border:1px solid #ddd">' + others + '</td></tr>';
}).join('');
const intro = submitted.length === 0
  ? '<p><b>Nobody has submitted a report for ' + esc(monthLabel) + ' yet.</b></p>'
  : '<p>' + submitted.length + ' of ' + total + ' members submitted for ' + esc(monthLabel) + '.</p>';
const html = '<div style="font-family:Arial,sans-serif">' + '<h2>Monthly reports - ' + esc(monthLabel) + '</h2>' + intro +
  '<table style="border-collapse:collapse"><thead><tr><th style="padding:6px;border:1px solid #ddd;background:#f6f8fa">Member</th><th style="padding:6px;border:1px solid #ddd;background:#f6f8fa">Status</th><th style="padding:6px;border:1px solid #ddd;background:#f6f8fa">Report link</th><th style="padding:6px;border:1px solid #ddd;background:#f6f8fa">Other files</th></tr></thead><tbody>' + tr + '</tbody></table></div>';
const telegramText = 'Monthly reports ' + month + ': ' + submitted.length + '/' + total + ' submitted.' +
  (submitted.length === 0 ? ' Nobody has submitted yet.' : '') +
  (missing.length ? '\nMissing: ' + missing.map(r => r.name).join(', ') : '\nEveryone submitted.');
const summaryInput = 'Month: ' + month + '. Submitted ' + submitted.length + ' of ' + total + '. Submitted members: ' + (submitted.map(r => r.name).join(', ') || 'none') + '. Missing members: ' + (missing.map(r => r.name).join(', ') || 'none') + '.';
return [{ json: { month, monthLabel, total, submittedCount: submitted.length, missingCount: missing.length, submitted, missing, rows, html, telegramText, summaryInput } }];

const month = $('Compute Previous Month (Reminders)').first().json.month;
const monthLabel = $('Compute Previous Month (Reminders)').first().json.monthLabel;
const isReal = (j) => j && Object.keys(j).length > 0;
const members = $('Read Members (Reminders)').all().map(i => i.json).filter(j => isReal(j) && j.email);
const subs = $('Read Submissions (Reminders)').all().map(i => i.json).filter(j => isReal(j) && j.member_email);
const missing = members.filter(m => !subs.some(s => String(s.member_email).trim().toLowerCase() === String(m.email).trim().toLowerCase() && String(s.month).trim().slice(0, 7) === month));
if (missing.length === 0) {
  return [{ json: { anyMissing: false, month, monthLabel, missingCount: 0, missingNames: '' } }];
}
const names = missing.map(m => m.name).join(', ');
return missing.map(m => ({ json: { anyMissing: true, month, monthLabel, name: m.name, email: m.email, missingCount: missing.length, missingNames: names } }));
